update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(38,null::text,$$Dever de submissão às normas de execução$$,$$Além das obrigações legais inerentes ao seu estado, o condenado deve submeter-se às normas de execução da pena.$$),
(39,null,$$Deveres do condenado$$,$$O artigo enumera dez deveres do condenado (incisos I a X), entre eles o comportamento disciplinado, a obediência ao servidor, a execução do trabalho, a submissão à sanção disciplinar, a indenização à vítima ou aos sucessores (inciso VII) e a higiene pessoal e asseio da cela (inciso IX). Pelo parágrafo único, aplica-se ao preso provisório, no que couber.$$),
(40,null,$$Respeito à integridade física e moral$$,$$Todas as autoridades devem respeitar a integridade física e moral dos condenados e dos presos provisórios.$$),
(41,null,$$Direitos do preso$$,$$O artigo enumera os direitos do preso (incisos I a XVI), como alimentação suficiente e vestuário (inciso I), atribuição de trabalho e remuneração (inciso II), previdência social (inciso III), entrevista pessoal e reservada com o advogado (inciso IX), visita do cônjuge, da companheira, de parentes e amigos (inciso X) e atestado de pena a cumprir, emitido anualmente (inciso XVI). Os direitos dos incisos V, X e XV podem ser suspensos ou restringidos por ato motivado do juiz da execução penal (§ 1º).$$),
(41,$$Art. 41-A$$,$$Monitoramento de encontros no parlatório ou virtuais$$,$$Os encontros no parlatório ou por meio virtual entre presos provisórios ou condenados vinculados a organizações criminosas ultraviolentas, grupos paramilitares ou milícias privadas e os seus visitantes poderão ser monitorados por captação audiovisual e gravação. O monitoramento pode ser requerido pelo delegado de polícia, pelo Ministério Público ou pela administração penitenciária (§ 1º).$$),
(41,$$Art. 41-B$$,$$Comunicações monitoradas entre advogado e cliente$$,$$O artigo trata do conteúdo das comunicações monitoradas entre advogado e cliente, quando o monitoramento houver sido autorizado por razões fundadas de conluio criminoso reconhecidas judicialmente: esse conteúdo é submetido à análise exclusiva do juízo competente para o controle da legalidade da investigação, distinto do juízo da instrução e do julgamento. Cabe ao juízo de controle decidir sobre a licitude, a pertinência e a necessidade da prova (§ 1º), e o conteúdo das comunicações indeferidas ou declaradas ilícitas não pode ser acessado, direta ou indiretamente, pelo juízo da instrução criminal (§ 3º).$$),
(42,null,$$Extensão ao preso provisório e à medida de segurança$$,$$As normas da Seção aplicam-se ao preso provisório e ao submetido à medida de segurança, no que couber.$$),
(43,null,$$Médico de confiança$$,$$É garantida a liberdade de contratar médico de confiança pessoal do internado ou do submetido a tratamento ambulatorial, por seus familiares ou dependentes, para orientar e acompanhar o tratamento. As divergências entre o médico oficial e o particular são resolvidas pelo juiz da execução (parágrafo único).$$),
(44,null,$$Conceito de disciplina$$,$$A disciplina consiste na colaboração com a ordem, na obediência às determinações das autoridades e seus agentes e no desempenho do trabalho. Sujeitam-se a ela o condenado à pena privativa de liberdade ou restritiva de direitos e o preso provisório (parágrafo único).$$),
(45,null,$$Legalidade das faltas e sanções disciplinares$$,$$Não há falta nem sanção disciplinar sem expressa e anterior previsão legal ou regulamentar. As sanções não podem colocar em perigo a integridade física e moral do condenado (§ 1º), é vedado o emprego de cela escura (§ 2º) e são vedadas as sanções coletivas (§ 3º).$$),
(46,null,$$Ciência das normas disciplinares$$,$$O condenado ou denunciado é cientificado das normas disciplinares no início da execução da pena ou da prisão.$$),
(47,null,$$Poder disciplinar na pena privativa de liberdade$$,$$Na execução da pena privativa de liberdade, o poder disciplinar é exercido pela autoridade administrativa, conforme as disposições regulamentares.$$),
(48,null,$$Poder disciplinar nas penas restritivas de direitos$$,$$Na execução das penas restritivas de direitos, o poder disciplinar é exercido pela autoridade administrativa a que estiver sujeito o condenado. Nas faltas graves, a autoridade representa ao juiz da execução, para os fins dos dispositivos que o parágrafo único indica.$$),
(49,null,$$Classificação das faltas disciplinares$$,$$As faltas disciplinares classificam-se em leves, médias e graves, e a legislação local especifica as leves e médias e as respectivas sanções. Pune-se a tentativa com a sanção correspondente à falta consumada (parágrafo único).$$),
(50,null,$$Faltas graves do condenado à pena privativa de liberdade$$,$$Comete falta grave o condenado à pena privativa de liberdade que incorrer em uma das condutas dos incisos I a IX, como incitar ou participar de movimento para subverter a ordem ou a disciplina (inciso I), fugir (inciso II), provocar acidente de trabalho (inciso IV), descumprir as condições do regime aberto (inciso V) ou recusar submeter-se à identificação do perfil genético (inciso VIII). O parágrafo único estende o artigo ao preso provisório, no que couber.$$),
(51,null,$$Faltas graves do condenado à pena restritiva de direitos$$,$$Comete falta grave o condenado à pena restritiva de direitos que descumprir injustificadamente a restrição imposta (inciso I), retardar injustificadamente o cumprimento da obrigação (inciso II) ou inobservar os deveres dos incisos II e V do artigo 39 (inciso III).$$),
(52,null,$$Regime disciplinar diferenciado$$,$$A prática de fato previsto como crime doloso constitui falta grave e, quando ocasionar subversão da ordem ou disciplina internas, sujeita o preso provisório ou condenado, nacional ou estrangeiro, ao regime disciplinar diferenciado, sem prejuízo da sanção penal. O caput fixa as características do regime nos incisos I a VII, entre elas a duração máxima de até 2 (dois) anos (inciso I) e o recolhimento em cela individual (inciso II). O § 1º aplica o regime também a presos que apresentem alto risco para a ordem e a segurança (inciso I) ou sobre os quais recaiam fundadas suspeitas de envolvimento em organização criminosa (inciso II); os incisos III e IV do § 1º constam como vetados.$$),
(53,null,$$Sanções disciplinares$$,$$Constituem sanções disciplinares a advertência verbal (inciso I), a repreensão (inciso II), a suspensão ou restrição de direitos (inciso III), o isolamento na própria cela ou em local adequado (inciso IV) e a inclusão no regime disciplinar diferenciado (inciso V).$$),
(54,null,$$Autoridade competente para aplicar sanções$$,$$As sanções dos incisos I a IV do art. 53 são aplicadas por ato motivado do diretor do estabelecimento, e a do inciso V (regime disciplinar diferenciado), por prévio e fundamentado despacho do juiz competente. A inclusão no regime depende de requerimento circunstanciado do diretor do estabelecimento ou de outra autoridade administrativa (§ 1º).$$),
(55,null,$$Fundamento das recompensas$$,$$As recompensas têm em vista o bom comportamento reconhecido em favor do condenado, sua colaboração com a disciplina e sua dedicação ao trabalho.$$),
(56,null,$$Espécies de recompensa$$,$$São recompensas o elogio (inciso I) e a concessão de regalias (inciso II). A legislação local e os regulamentos estabelecem a natureza e a forma de concessão das regalias (parágrafo único).$$),
(57,null,$$Critérios de aplicação das sanções$$,$$Na aplicação das sanções disciplinares levam-se em conta a natureza, os motivos, as circunstâncias e as consequências do fato, bem como a pessoa do faltoso e seu tempo de prisão. Nas faltas graves, aplicam-se as sanções dos incisos III a V do art. 53 (parágrafo único).$$),
(58,null,$$Limite de duração das sanções$$,$$O isolamento, a suspensão e a restrição de direitos não podem exceder trinta dias, ressalvada a hipótese do regime disciplinar diferenciado. O isolamento é sempre comunicado ao juiz da execução (parágrafo único).$$),
(59,null,$$Procedimento disciplinar$$,$$Praticada a falta disciplinar, deve ser instaurado o procedimento para sua apuração, conforme regulamento, assegurado o direito de defesa. A decisão será motivada (parágrafo único).$$),
(60,null,$$Isolamento preventivo$$,$$A autoridade administrativa pode decretar o isolamento preventivo do faltoso por até dez dias. A inclusão preventiva no regime disciplinar diferenciado, no interesse da disciplina e da averiguação do fato, depende de despacho do juiz competente. O tempo de isolamento ou de inclusão preventiva é computado no período de cumprimento da sanção disciplinar (parágrafo único).$$),
(61,null,$$Órgãos da execução penal$$,$$São órgãos da execução penal o Conselho Nacional de Política Criminal e Penitenciária (inciso I), o Juízo da Execução (inciso II), o Ministério Público (inciso III), o Conselho Penitenciário (inciso IV), os Departamentos Penitenciários (inciso V), o Patronato (inciso VI), o Conselho da Comunidade (inciso VII) e a Defensoria Pública (inciso VIII).$$),
(62,null,$$Conselho Nacional de Política Criminal e Penitenciária$$,$$O Conselho Nacional de Política Criminal e Penitenciária tem sede na Capital da República e é subordinado ao Ministério da Justiça.$$),
(63,null,$$Composição do Conselho Nacional$$,$$O Conselho é integrado por 13 (treze) membros designados por ato do Ministério da Justiça, dentre professores e profissionais da área do Direito Penal, Processual Penal, Penitenciário e ciências correlatas, bem como representantes da comunidade e dos Ministérios da área social. O mandato dura 2 (dois) anos, renovado 1/3 (um terço) em cada ano (parágrafo único).$$),
(64,null,$$Atribuições do Conselho Nacional$$,$$Incumbe ao Conselho, em âmbito federal ou estadual, entre outras atribuições dos incisos I a X: propor diretrizes da política criminal (inciso I), estimular a pesquisa criminológica (inciso IV), estabelecer regras sobre a arquitetura de estabelecimentos penais e casas de albergados (inciso VI), inspecionar e fiscalizar os estabelecimentos penais (inciso VIII) e representar à autoridade competente pela interdição, total ou parcial, de estabelecimento penal (inciso X).$$),
(65,null,$$Competência para a execução penal$$,$$A execução penal compete ao juiz indicado na lei local de organização judiciária e, na sua ausência, ao da sentença.$$),
(66,null,$$Competência do juiz da execução$$,$$Compete ao juiz da execução, entre outras atribuições dos incisos I a X: aplicar lei posterior que favoreça o condenado (inciso I), declarar extinta a punibilidade (inciso II), decidir sobre soma ou unificação de penas, progressão ou regressão de regimes, detração e remição, suspensão condicional, livramento condicional e incidentes da execução (inciso III, a a f), autorizar saídas temporárias (inciso IV), determinar medidas como a conversão de penas e a aplicação de medida de segurança (inciso V), zelar pelo correto cumprimento da pena (inciso VI), inspecionar mensalmente os estabelecimentos penais (inciso VII), interditá-los (inciso VIII) e emitir anualmente atestado de pena a cumprir (inciso X).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;